            while not self._isLoadSuccess do
                coroutine.yield(Yielders.EndOfFrame)
            end
        end)
        --等屏幕黑了再开始加载  要不ka
        coroutine.yield(WaitForSeconds(time))
        coroutine.yield(WaitForSeconds(0.2))

        sceneManagement:AppendScene(self._curSceneId, true)
        while not sceneManagement:GetAppendingScene(self._curSceneId) do
            coroutine.yield(Yielders.EndOfFrame)
        end

        self._sceneCam = sceneManagement:GetSceneInstance(self._curSceneId):GetCacheObjectByName("Main Camera")
        local parGo = sceneManagement:GetSceneInstance(self._curSceneId):GetCacheObjectByName("FishRolePar")
