        if checkInt(playerComp.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE then
            rolePath = "Arts/Prefab_home/20038_home.prefab"
            bonePath = "Arts/Prefab_home/20038_home_empty.prefab"
        else
            rolePath = "Arts/Prefab_home/20037_home.prefab"
            bonePath = "Arts/Prefab_home/20037_home_empty.prefab"
        end
        
        local boneLoader = ResourceModule.LoadBundleAsync(bonePath, nil, true)
        while not boneLoader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end
        self._boneGo = boneLoader:Instantiate(parGo.transform)
        self._avatar = KTool.GetOrAddComponent(self._boneGo, typeof(CharacterAvatar))

        local roleLoader = ResourceModule.LoadBundleAsync(rolePath, nil, true)
        while not roleLoader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end

        -- self._roleGo = CfUtils.InstantiateGo(self._roleLoader.ResultObject.gameObject, parGo)
        self._roleGo = roleLoader:Instantiate(nil)
        roleLoader:Release()
        self._boneGo = self._roleGo
        KTool.SetActive(self._roleGo, false)
        self._roleGo = self._avatar.gameObject

        --[[
        if not self._avatar.Inited then
            self._avatar:Init()
            self._avatar.Inited = true
        end

        self._avatar:AddBakeObject(self._boneGo)
        self._avatar:AddBakeObject(self._ganGo)
        self._avatar:StartBake()
        ]]

        --self:ChangeRodModel(checkNumber(fishingComponent:GetCurEquipRodId()))

        self._roleGo.name = string.stripExtension(string.stripFileName(vo.rolePath))
        self._roleAni = KTool.GetOrAddComponent(self._roleGo, typeof(Animator))
        if self._roleAni then
            local controllerPath = ""
            if checkInt(playerComp.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE then
                controllerPath = "RuntimeController/Animator_fishing/20038_fishing.overrideController"
            else
                controllerPath = "RuntimeController/Animator_fishing/20037_fishing.overrideController"
            end

            self._animLoader = ResourceModule.LoadBundleSync(controllerPath, nil, true)
            if self._animLoader.IsSuccess then
                local animCtrl = GameObject.Instantiate(self._animLoader.ResultObject)
                self._roleAni.runtimeAnimatorController = animCtrl
            end
        end

        self._fishLineGo = self._roleGo.transform:Find("Unity_Export_Grp/DeformationScale_Grp/DeformationSystem/root_move_jnt/weapon_move_jnt/weapon_3_move_jnt/fishing_root_Jnt/fishing_Jnt1/fishing_Jnt2/fishing_extra_Jnt1/fishing_Jnt3/fishing_extra_Jnt2/fishing_Jnt4/fishing_extra_Jnt3")
