---InitFishingData
---初始化钓鱼数据
function FishingMgr:InitFishingData(fishId, placeId, castRodType, refreshTalkCb, isGuide, refreshDamageCb)
    self._talkTime = 0
    self._isGuide = checkBool(isGuide)
    self._curFishId = checkNumber(fishId)
    self._curFishAttrVo = FishingUtils.GetFishingSpeciesAttrVo(self._curFishId)
    if not self._curFishAttrVo then
        return
    end
    self._curFishLineId = checkNumber(fishingComponent:GetCurEquipWireId(placeId))
    self._curFishReelId = checkNumber(fishingComponent:GetCurEquipReelId(placeId))


    self._castRodType = castRodType
    self._curForce = FishingUtils.GetInitialForce()    
    self._curFishingRodId = checkNumber(fishingComponent:GetCurEquipRodId(placeId))
    self._refreshTalkCb = refreshTalkCb
    self._refreshDamageCb = refreshDamageCb

    --初始化里转换伤害系数
    self._pullForceCompairMap = {}
    local t = FishingUtils.GetAllFishingPullPowerVo()
    if t then
        local num = 0
        for k, v in pairs(t) do
            num = num + checkNumber(v.weight)
            v.maxWight = num
            table.insert(self._pullForceCompairMap, v)
            --self._pullForceCompairMap[checkString(num)] = v --FishingUtils.GetDamageFactorByVo(v)

            if checkNumber(v.id) == FishingUtils.GetAutoTargetForceId() then
                self._autoTargetForceVo = v
            end
        end
        self._maxForce = num
    end

    self._fishStatusCompair = {}
    local t1 = CfUtils.Split(self._curFishAttrVo.escapeBlock)
    local t2 = CfUtils.Split(self._curFishAttrVo.ordinaryBlock)
    if t1 and t2 then
        local len = math.min(#t1, #t2)
        for i = 1, len do
            table.insert(self._fishStatusCompair, checkNumber(t1[i]))
            table.insert(self._fishStatusCompair, checkNumber(t2[i]))
        end
        if #t1 > #t2 then
            table.insert(self._fishStatusCompair, checkNumber(t1[#t1]))
        elseif #t2 > #t1 then
            table.insert(self._fishStatusCompair, checkNumber(t2[#t2]))
        end
        self._fishStatusIndex = 1
    end

    self._time = 0  
    self._allTime = 0  
    self:SetTieRod(false)
    self._curFishStatus = ConstantsFishing.FishStatus.Common
    self:InitBaseData()

    self._loopAniX = false        --循环动作的x
    self._aniXNum = 0             --动作的x值
    self._fishLRRunTime = 0       --
    self._normalLRRun = 1         --左右移动时候的方向  
    self:RandomRunTime()
    self._curDamage = 0
    self._forwardTime = 0         --往前游的时间

    self._writeStr = ""
    self._writeTime = 0
    self:WriteStr("第0秒 ".." fishId:"..self._curFishId.." 最大血量："..self._maxHp.." 最大距离："..self._maxDis.."\n")

    self._isFishing = true
end

--初始化基础属性
function FishingMgr:InitBaseData()
    self._baseDamage = FishingUtils.GetFishingRodDamageById(self._curFishingRodId) + FishingUtils.GetFishingPropsAdditionValue(ConstantsFishing.AdditionType.AddDamage, nil, self._curFishPlaceId)
    local globalTalentMgr = GlobalTalentMgr:GetInstance()
    self._baseDamage = globalTalentMgr:CalcNum(self._baseDamage, Constants.GlobalTalentEffectId.Id_16, false, function(data)
        return true
    end)
    local hps = CfUtils.Split(self._curFishAttrVo.life)
    self._curHp = math.random(checkInt(hps[1]), checkInt(hps[2]))
    self._maxHp = self._curHp  
    self._curDis = checkInt(self._curFishAttrVo.initialDistance)              --当前的距离  
    self._curFishLineVo = FishingUtils.GetFishingLineVo(self._curFishLineId)
    if self._curFishLineVo then
        self._maxDis = checkNumber(self._curFishLineVo.length)
    end
    local vo = FishingUtils.GetFishingReelVo(self._curFishReelId)
    if vo then
        self._reelSpeed = checkNumber(vo.speed)
    end

    self:InitAddDamage()
    self._fishGo.transform.localPosition = Vector3(0, 0, 0) --self._curFishPlaceVo.startPoint
    self:RefreshFishGoPos(self._curDis)
end

--初始化伤害加成数值
function FishingMgr:InitAddDamage()
    local num = FishingUtils.GetFishingAdditionValueByAccompanyCard(self._curFishPlaceId, ConstantsFishing.AdditionType.AddDamagePer)
    num = num + FishingUtils.GetFishingPropsAdditionValue(ConstantsFishing.AdditionType.AddDamagePer, nil, self._curFishPlaceId)
    self._addDamageValue = num
end

--当前的力速度
function FishingMgr:GetCurForceSpeed()
    local num = 0
    if self._isTieRod then
        num = self:GetAddForce()

        local vo = self:GetCurFishingPullPowerVo()
        if not vo then
            return num
        end
        if checkNumber(vo.id) == 6 then
            if self._curFishLineVo then
                num = num * (1 - checkNumber(self._curFishLineVo.toughness))
            end
        end
    else
        num = self:GetReduceForce()
    end
    return num
end

--获取减少的力
function FishingMgr:GetReduceForce()
    local force = 0
    if self:IsRunAwayStatus() then
        force = FishingUtils.GetRunAwayStatusUpForce(self._curFishId)
    else
        force = FishingUtils.GetCommonStatusUpForce(self._curFishId)
    end
    return force
end

--获取增加的力
function FishingMgr:GetAddForce()
    local force = 0
    if self:IsRunAwayStatus() then
        force = FishingUtils.GetRunAwayStatusDownForce(self._curFishId)
    else
        force = FishingUtils.GetCommonStatusDownForce(self._curFishId)
    end
    return force
end

