--当前的速度
function FishingMgr:GetCurSpeed()
    local vo = self:GetCurFishingPullPowerVo()
    if not vo then
        return 0
    end
    local fishSpeed = checkNumber(self._curFishAttrVo.speed)
    local baseSpped = fishSpeed * (1 + FishingUtils.GetFishingAdditionValueByVo(vo, ConstantsFishing.AdditionType.AddFishSpeed, ConstantsFishing.FishStatus.Common))

    local speed = 0
    local isRunAway = self:IsRunAwayStatus()
    --逃逸
    if isRunAway then
        --逃逸速度加成
        local runAwaySpeedAdd = FishingUtils.GetFishingAdditionValueByVo(vo, ConstantsFishing.AdditionType.AddFishSpeed, ConstantsFishing.FishStatus.RunAway)
        --本身的逃逸系数
        local runAwayCoefficient = checkNumber(self._curFishAttrVo.escapeCoefficient)
        --拉杆
        if self._isTieRod then
            speed = math.max(baseSpped * (runAwaySpeedAdd + runAwayCoefficient) - self._reelSpeed, 0.2 * fishSpeed * runAwayCoefficient)
        else
            speed = baseSpped * (runAwaySpeedAdd + runAwayCoefficient)
        end 
    else
        if self._isTieRod then
            speed = math.max(baseSpped - self._reelSpeed, -0.5 * self._reelSpeed)
        else
            speed = baseSpped
        end
    end
    return speed
end

--闲置的时候
function FishingMgr:OnUpdataIdle()
    if self._curRoleStatus ~= ConstantsFishing.RoleStatus.Idle then
        return
    end

    --一秒计算一次伤害
    if self._curIdleTime >= self._idleTargetTime then
        self._curIdleTime = 0
        local randomNum = math.random(6)
        self:SetIdlePar(randomNum)
    else
        self._curIdleTime = self._curIdleTime + CS.UnityEngine.Time.deltaTime
    end
end

