    self:RefreshAllPar()
end

function FishingMgr:ChangeRoleStatus(status)
    if status == ConstantsFishing.RoleStatus.Idle then
        self:RefreshAllPar()
        self._curIdleTime = 0
        --self:ForceIdle()
    elseif status == ConstantsFishing.RoleStatus.Cast then
        --self:ForceIdle()
    end
    self._curRoleStatus = status
end

--刷新动作的拉杆参数
function FishingMgr:RefreshAniForce()
    local forcePercentage = self._curForce / self._maxForce    --力百分比

    local y = forcePercentage * ConstantsFishing.AniForceCoefficient 
    
    --可以循环x值了
    self._loopAniX = forcePercentage >= ConstantsFishing.AniForceLRNum
    local x = self._aniXNum

    self:SetPullXYPar(x, y)
end

function FishingMgr:GetCurDamage()
    return self._curDamage
end

