end

--钓鱼中的时候
function FishingMgr:OnUpdata()
    if not self._isFishing then
        return
    end
    self:RefreshFishStatus()

    --一秒计算一次伤害
    if self._time >= 1 then
        self._writeStr = self._writeStr.."\n"
        self:WriteStr("第"..(math.floor(self._allTime / 1)).."秒")
        self:CalculateDamage()
        if self._refreshDamageCb then
            self._refreshDamageCb()
        end
        self._time = 0
    else
        self._time = self._time + CS.UnityEngine.Time.deltaTime
    end

    --引导只能成功
    if self._isGuide then
        if self._curHp <= 0 or self._curDis <= 0 then
            self._isFishing = false
            local forceScale = self._curForce / self._maxForce
            Events.Broadcast(Constants.EventNames.FishFinish, {type = ConstantsFishing.FishFinishType.Success, forceScale = forceScale})
        end
    else
        if self._curDis >= self._maxDis then
            local forceScale = self._curForce / self._maxForce
            self._isFishing = false
            Events.Broadcast(Constants.EventNames.FishFinish, {type = ConstantsFishing.FishFinishType.DisExceed, forceScale = forceScale})
        elseif self._curHp <= 0 or self._curDis <= 0 then
            local forceScale = self._curForce / self._maxForce
            self._isFishing = false
            Events.Broadcast(Constants.EventNames.FishFinish, {type = ConstantsFishing.FishFinishType.Success, forceScale = forceScale})
        elseif self._curForce >= self._maxForce then      --断线
            local forceScale = self._curForce / self._maxForce
            self._isFishing = false
            Events.Broadcast(Constants.EventNames.FishFinish, {type = ConstantsFishing.FishFinishType.BreakLine, forceScale = forceScale})
        elseif self._curForce <= 0 then     --挣脱
            local forceScale = self._curForce / self._maxForce
            self._isFishing = false        
            Events.Broadcast(Constants.EventNames.FishFinish, {type = ConstantsFishing.FishFinishType.BreakFree, forceScale = forceScale})
        end
    end

    self._curForce = self._curForce + self:GetCurForceSpeed() * CS.UnityEngine.Time.deltaTime
    if self._curForce <= 0 then
        self._curForce = 0
    elseif self._curForce >= self._maxForce then 
        self._curForce = self._maxForce
    end

    local dis = self:GetCurSpeed() * CS.UnityEngine.Time.deltaTime
    --跟新距离
    self._curDis = self._curDis + dis
    self._curDis = math.max(self._curDis, 0)
    self:RefreshFishGoPos(dis)
    self:RefreshLineRenderPos()

    self._allTime = self._allTime + CS.UnityEngine.Time.deltaTime

    if self._loopAniX then
        if self._aniXNum >= 1 then
            self._normalX = -1
        elseif self._aniXNum <= -1 then
            self._normalX = 1
        end
        self._aniXNum = self._aniXNum + CS.UnityEngine.Time.deltaTime * self._normalX * ConstantsFishing.AniForceLRCoefficient
    else
        --平滑到0
        if self._aniXNum > 0 then
            self._aniXNum = self._aniXNum - CS.UnityEngine.Time.deltaTime * ConstantsFishing.AniForceLRCoefficient
            if math.abs(self._aniXNum) <= 0.1 then
                self._aniXNum = 0
            end
        elseif self._aniXNum < 0 then
            self._aniXNum = self._aniXNum + CS.UnityEngine.Time.deltaTime * ConstantsFishing.AniForceLRCoefficient
            if math.abs(self._aniXNum) <= 0.1 then
                self._aniXNum = 0
            end
        end
    end

    self:RefreshShuiHuaEffectActive()
    --刷新动作
    self:RefreshAniForce()
    self._forwardTime = self._forwardTime + CS.UnityEngine.Time.deltaTime

    if self._writeTime >= 0.3 then
        local forceStr = string.format("%.2f", self._curForce)
        local s = "距离："..self._curDis.." 拉力："..forceStr
        s = s.." 血量："..self._curHp.." 速度："..self:GetCurSpeed()
        self:WriteStr(s)
        self._writeTime = 0
    else
        self._writeTime = self._writeTime + CS.UnityEngine.Time.deltaTime
    end
end

function FishingMgr:RefreshFishGoPos(dis)
    --local maxDis = checkNumber(self._curFishAttrVo.advanceDistance)
    if self._forwardTime < checkNumber(self._curFishAttrVo.forwardRunTime) then
        local pos = self._fishGo.transform.localPosition + self._fishGo.transform.forward * checkNumber(self._curFishAttrVo.forwardRunSpeed) --* 0.05
        self._fishGo.transform.localPosition = pos
        self._fishForwardPos = pos
    else
        if self._fishLRRunTime >= self._targetLRTime then    
            self._normalLRRun = self._normalLRRun * -1  
            self:RandomRunTime()
            self._fishLRRunTime = 0
        end
        local pos = self._fishGo.transform.localPosition + self._fishGo.transform.right * 0.1 * self:GetLRSpeed() * self._normalLRRun * 0.5
        local maxDis = self:GetRunLimitDis(self._normalLRRun == 1)
        local dis = Vector3.Distance(pos, self._fishForwardPos)

        local isR = CS.UnityEngine.Vector3.Cross(self._fishForwardPos, pos).y > 0  

        --大于最大距离 立即相反
        if dis >= maxDis then
            --全是往右
            if isR and self._normalLRRun == 1 then
                self._fishLRRunTime = self._targetLRTime
            elseif not isR and self._normalLRRun == -1 then
                self._fishLRRunTime = self._targetLRTime
            else
                self._fishGo.transform.localPosition = pos
                self._fishLRRunTime = self._fishLRRunTime + CS.UnityEngine.Time.deltaTime
            end
        else
            self._fishGo.transform.localPosition = pos
            self._fishLRRunTime = self._fishLRRunTime + CS.UnityEngine.Time.deltaTime
        end
    end
end

--随机一次时间摇晃的时间
function FishingMgr:RandomRunTime()
    local t = FishingUtils.GetFishLRRandomTime()
    self._targetLRTime = math.random(t[1], t[2])
end

--上下自由移动时候的速度
function FishingMgr:GetLRSpeed()
    local speed = 0
    if self._curFishStatus == ConstantsFishing.FishStatus.RunAway then
        speed = checkNumber(self._curFishAttrVo.escapeSpeed)
    else    
        speed = checkNumber(self._curFishAttrVo.ordinarySpeed)
    end
    return speed
end

function FishingMgr:WriteStr(s)
    local fishStatusStr = "普通状态  "
    if self._curFishStatus == ConstantsFishing.FishStatus.RunAway then
        fishStatusStr = "逃逸状态  "
    end
    local btnStr = " 拉线 "
    if not self._isTieRod then
        btnStr = " 放线 "
    end
    local time = string.format("%.2f", self._allTime)
    self._writeStr = self._writeStr..time..": "..fishStatusStr..btnStr..s.."\n"
end

--计算伤害
function FishingMgr:CalculateDamage()
    self._curDamage = self._baseDamage * (self:GetCurForceDamageFactor() + self._addDamageValue)
    self:WriteStr("收到伤害："..self._curDamage.." 基础伤害："..self._baseDamage.." 拉力加成："..self:GetCurForceDamageFactor().." 道具加成："..self._addDamageValue)
    self._curHp = self._curHp - self._curDamage
end

--获取当前力的伤害系数
function FishingMgr:GetCurForceDamageFactor()
    local vo = self:GetCurFishingPullPowerVo()
    if not vo then
        return 0
    end

    return FishingUtils.GetDamageFactorByVo(vo)
end

--获取当前力的vo
---@return FishingPullPowerVo
function FishingMgr:GetCurFishingPullPowerVo()
    if not self._pullForceCompairMap then
        return nil
    end

    local num = 0
    for k, v in pairs(self._pullForceCompairMap) do
        num = num + checkNumber(k)
        if self._curForce <= v.maxWight then
            return v
        end
    end
    return self._pullForceCompairMap[#self._pullForceCompairMap]
end

--是否在逃逸状态
function FishingMgr:IsRunAwayStatus()
    return self._curFishStatus == ConstantsFishing.FishStatus.RunAway
end

--刷新鱼的状态
function FishingMgr:RefreshFishStatus()
    if not self._fishStatusCompair then
        self._curFishStatus = ConstantsFishing.FishStatus.Common
        return
    --没数据时不改变
    elseif #self._fishStatusCompair <= 0 then
        return
    end

    local compairValue = self._fishStatusCompair[1]
    -- -1直接退出
    if compairValue < 0 then
        table.remove(self._fishStatusCompair, 1)
        --不在逃逸 直接相反
        if (self._fishStatusIndex % 2) == 0 then
            self._curFishStatus = ConstantsFishing.FishStatus.Common
        else
            self._curFishStatus = ConstantsFishing.FishStatus.RunAway
        end
        return
    end

    local isHandle = false
    if checkNumber(self._curFishAttrVo.type) == ConstantsFishing.FishStatusType.Hp then
        local value = self._curHp / self._maxHp
        if value <= compairValue then
            isHandle = true
        end
    elseif checkNumber(self._curFishAttrVo.type) == ConstantsFishing.FishStatusType.Time then
        local value = self._allTime
        if value >= compairValue then
            isHandle = true
        end
    end 

    --触发条件
    if isHandle then
        table.remove(self._fishStatusCompair, 1)
        --不在逃逸
        if (self._fishStatusIndex % 2) == 0 then
            self._curFishStatus = ConstantsFishing.FishStatus.Common
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_water_small)
        else
            self._curFishStatus = ConstantsFishing.FishStatus.RunAway
            CriWareUtils.PlaySe(UISheets.SFX_Fishing.path, UISheets.SFX_Fishing.fishing_water_big)
        end
        if self._refreshTalkCb and self._talkTime > 0 then
            self._refreshTalkCb("30"..self._curFishStatus)
        end
        self._talkTime = self._talkTime + 1

        if self._fishStatusCompair[1] < 0 then
        else
            self._fishStatusIndex = self._fishStatusIndex + 1
        end
    end
end

function FishingMgr:GetFishGo()
    return self._fishGo
end

--获取当前鱼的状态
function FishingMgr:GetCurFishStatus()
    return self._curFishStatus
end

--水花特效 一开始的
function FishingMgr:SetShuiHuaEffectActive(isShow, qteType)
    if isNull(self._fishPar) then
        return
    end

    if IsNull(self._fx_diaoyu_water01Go) then
        self._fx_diaoyu_water01Go = self._fishPar.transform:Find("fx_diaoyu_water01")
    end

    if not isNull(self._fx_diaoyu_water01Go) then
        if isShow then
            local pos 
            if qteType == ConstantsFishing.CastRodType.Generally then 
                pos = self._curFishPlaceVo.commonPoint
            elseif qteType == ConstantsFishing.CastRodType.Well then 
                pos = self._curFishPlaceVo.goodPoint
            elseif qteType == ConstantsFishing.CastRodType.Perfect then 
                pos = self._curFishPlaceVo.perfectPoint
            end

            self._fx_diaoyu_water01Go.transform.localPosition = pos
        end
        KTool.SetActive(self._fx_diaoyu_water01Go, isShow)
    end
end

function FishingMgr:RefreshShuiHuaEffectActive()
    if IsNull(self._fx_diaoyu_water02Go) then
        self._fx_diaoyu_water02Go = self._fishGo.transform:Find("fx_diaoyu_water02")
    end
    if IsNull(self._fx_diaoyu_water03Go) then
        self._fx_diaoyu_water03Go = self._fishGo.transform:Find("fx_diaoyu_water03")
    end

    if not IsNull(self._fx_diaoyu_water02Go) then
        KTool.SetActive(self._fx_diaoyu_water02Go, self._curFishStatus == ConstantsFishing.FishStatus.Common)
    end

    if not IsNull(self._fx_diaoyu_water03Go) then
        KTool.SetActive(self._fx_diaoyu_water03Go, self._curFishStatus == ConstantsFishing.FishStatus.RunAway)
    end
end

function FishingMgr:HideShuiHuaEffect()
    if not IsNull(self._fx_diaoyu_water02Go) then
        KTool.SetActive(self._fx_diaoyu_water02Go, false)
    end
    if not IsNull(self._fx_diaoyu_water03Go) then
        KTool.SetActive(self._fx_diaoyu_water03Go, false)
    end
end

function FishingMgr:SetLineRenderActive(isShow)
    if isNull(self._lineRender) then
        return
    end
    KTool.SetActive(self._lineRender.gameObject, isShow)
end

--获取左右跑得时候得范围
function FishingMgr:GetRunLimitDis(isLeft)
    if not self._curFishAttrVo then
        return 0
    end
    local t = CfUtils.Split(self._curFishAttrVo.distanceLimits)
    if isLeft then
        return checkNumber(t[1])
    else
        return checkNumber(t[2])
    end
end

function FishingMgr:ChangeRodModel(id)
    local vo = FishingUtils.GetFishingGoodsVoById(id)
    if not vo then
        return
    end
    --vo.asset = "Arts/Model/Model_prefab/item/fake_100_fishing_rod11.prefab"
    local loader
    if checkInt(playerComp.playerDojo.gender) == Constants.PLAYER_GENDER.FEMALE then
        loader = self:GetLoader(vo.asset2)
    else
        loader = self:GetLoader(vo.asset1)
    end

    if isNull(loader) then
        return
    end
    self._avatar:ClearObject()

    if not isNull(self._ganGo) then
        --GameObject.Destroy(self._ganGo)
    end

    self._ganGo = loader:Instantiate(nil)
    KTool.SetActive(self._ganGo, false)

    if not self._avatar.Inited then
        self._avatar:Init()
        self._avatar.Inited = true
    end

    self._avatar:AddBakeObject(self._boneGo)
    self._avatar:AddBakeObject(self._ganGo)
    self._avatar:StartBake()
end

function FishingMgr:GetLoader(path)
    if not self._loaders then
        self._loaders = {}
    end
    path = checkString(path)
    if isNull(self._loaders[path]) then
        local loader = ResourceModule.LoadBundleSync(path)
        if loader.IsSuccess then
            self._loaders[path] = loader
        else
            loader:Release()
            return nil
        end
    end
    return self._loaders[path]
end

function FishingMgr:Clear()
    RenderSettings.customReflection = self._lastCustomReflection --CS.UnityEngine.Rendering.DefaultReflectionMode.Custom

    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    -- if self._roleLoader then
    --     self._roleLoader:Release(true)
    -- end
    if self._animLoader then
        self._animLoader:Release(true)
    end
    cs_coroutine.yield_return(sceneManagement:UnloadAppendedSceneById(self._curSceneId))

    self:__delete()
    self.Destroy(self)   --这个好像没用
end

return FishingMgr
